def nextPalindrome(digits):
    n = len(digits)
    res = list(digits)
    for i in range(n // 2):
        res[n - 1 - i] = res[i]
    if res > digits:
        return res
    i = (n - 1) // 2
    while i >= 0 and res[i] == 9:
        res[i] = 0
        i -= 1
    if i < 0:
        return [1] + [0] * (n - 1) + [1]
    res[i] += 1
    for k in range(n // 2):
        res[n - 1 - k] = res[k]
    return res
